#!/usr/bin/env bash
# Patch 96 voor hrmforce-site: takenlijst van Dion na de livegang (23-10-2026).
#
#   bash toepassen-96.sh
#
# - Wekelijkse updates (1.206 pagina's in zes talen) op noindex en uit de sitemap
# - Blok "Oefen eerst" in vier artikelen (intelligentietest-volwassenen, matrigma,
#   gemiddeld-iq, mbti) met de oefentests abstract redeneren en cijferreeksen
# - Knop "Voeg hrmforce toe als voorkeursbron" onder de kennisbankartikelen
# - Tarieven: pay-as-you-go vanaf EUR 34,- (bandbreedte 34 tot 423 uit de shop);
#   Pro "vanaf EUR 1,- per medewerker per maand, afhankelijk van de gekozen modules"
# - Overal "29 taalversies" in plaats van "14 talen"
# - Formulier op de assessmentpagina's: binnen 24 uur contact voor een demo
# - /assessments/cognitieve-test/ samengevoegd met de Ability Scan (301, alle talen)
# - Facet5-URL naar /persoonlijkheidstest/
# - Twee SHL-pdf's krijgen X-Robots-Tag: noindex (public/_headers)
set -euo pipefail
cd "$(dirname "$0")"
[ -f functions/_middleware.js ] || { echo "Draai dit vanuit de hoofdmap van hrmforce-site."; exit 1; }

